package com.bank.directory;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class HashMapDemo {

    private static final Logger log = Logger.getLogger(HashMapDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountDirectory directory = new AccountDirectory();

        directory.register("SAV2001", new BigDecimal("1000000"));
        directory.register("CUR3001", new BigDecimal("250000"));

        log.info(() -> "Rajesh balance: Rs." + directory.balanceOf("SAV2001"));
        log.info(() -> "Priya balance: Rs." + directory.balanceOf("CUR3001"));

        // Rajesh transfers 50000 to Priya — update both balances by key.
        directory.register("SAV2001", new BigDecimal("950000"));
        directory.register("CUR3001", new BigDecimal("300000"));
        log.info(() -> "After transfer, Rajesh: Rs." + directory.balanceOf("SAV2001"));

        // Unknown account returns a safe default instead of null.
        log.info(() -> "Unknown account balance: Rs." + directory.balanceOf("XXX9999"));
    }
}

