class AccountDirectory {

    private static final Logger log = Logger.getLogger(AccountDirectory.class.getName());

    // Key = account number, Value = balance. Average O(1) lookup.
    private final java.util.Map<String, BigDecimal> balances = new java.util.HashMap<>();

    void register(String accountNo, BigDecimal balance) {
        balances.put(accountNo, balance); // insert or replace
        log.info(() -> "PUT " + accountNo + " = Rs." + balance);
    }

    BigDecimal balanceOf(String accountNo) {
        // getOrDefault avoids a null and returns zero for unknown accounts.
        return balances.getOrDefault(accountNo, BigDecimal.ZERO);
    }

    boolean exists(String accountNo) {
        return balances.containsKey(accountNo);
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
